import{_ as i,c as s,o as a,a2 as t}from"./chunks/framework.CFHYvIe4.js";const m=JSON.parse('{"title":"Cross-Compatibility","description":"","frontmatter":{},"headers":[],"relativePath":"guide/cross-compatibility.md","filePath":"guide/cross-compatibility.md","lastUpdated":1756461828000}'),o={name:"guide/cross-compatibility.md"};function l(n,e,r,p,d,h){return a(),s("div",null,e[0]||(e[0]=[t(`<h1 id="cross-compatibility" tabindex="-1">Cross-Compatibility <a class="header-anchor" href="#cross-compatibility" aria-label="Permalink to &quot;Cross-Compatibility&quot;">​</a></h1><p>One of the main goals of S1API is to enable mod developers to write code that works seamlessly across both Mono and Il2Cpp builds of Schedule One. This guide explains how to achieve cross-compatibility in your mods.</p><h2 id="the-challenge" tabindex="-1">The Challenge <a class="header-anchor" href="#the-challenge" aria-label="Permalink to &quot;The Challenge&quot;">​</a></h2><p>Schedule One exists in two different build flavors:</p><ol><li><strong>Mono</strong>: The original build using Mono as the .NET runtime</li><li><strong>Il2Cpp</strong>: A newer build where the .NET code has been converted to C++</li></ol><p>These two builds handle many things differently, especially when it comes to:</p><ul><li>Type references and reflection</li><li>Memory management</li><li>Method pointers and delegates</li><li>Native interop</li></ul><p>Without S1API, mod developers would need to create separate versions of their mods for each build, duplicating effort and maintenance.</p><h2 id="best-practices-for-cross-compatible-mods" tabindex="-1">Best Practices for Cross-Compatible Mods <a class="header-anchor" href="#best-practices-for-cross-compatible-mods" aria-label="Permalink to &quot;Best Practices for Cross-Compatible Mods&quot;">​</a></h2><p>Follow these guidelines to ensure your mods work across both builds:</p><h3 id="do" tabindex="-1">DO: <a class="header-anchor" href="#do" aria-label="Permalink to &quot;DO:&quot;">​</a></h3><ul><li>✅ Use S1API interfaces and classes instead of direct game references</li><li>✅ Use the provided manager classes (ItemManager, ProductManager, etc.)</li><li>✅ Extend built-in classes like Quest, PhoneApp, etc. for standard functionality</li><li>✅ Test your mod on both Mono and Il2Cpp if possible</li></ul><h3 id="don-t" tabindex="-1">DON&#39;T: <a class="header-anchor" href="#don-t" aria-label="Permalink to &quot;DON&#39;T:&quot;">​</a></h3><ul><li>❌ Reference game assemblies directly</li><li>❌ Use raw reflection on game types</li><li>❌ Make assumptions about memory layout or object references</li><li>❌ Use platform-specific code without proper conditional compilation</li></ul><h2 id="conditional-compilation" tabindex="-1">Conditional Compilation <a class="header-anchor" href="#conditional-compilation" aria-label="Permalink to &quot;Conditional Compilation&quot;">​</a></h2><p>In rare cases where you need platform-specific code, S1API provides preprocessor symbols:</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">#</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MONO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Mono-specific code</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">#</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">elif</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">IL2CPP</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Il2Cpp-specific code</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">#</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">endif</span></span></code></pre></div><p>However, this should be a last resort. Aim to use S1API&#39;s cross-platform abstractions whenever possible.</p>`,18)]))}const u=i(o,[["render",l]]);export{m as __pageData,u as default};
